"/* SPDX-License-Identifier: GPL-3.0-or-later */\n(() => {\n  'use strict';\n  const $ = id => document.getElementById(id);\n  $('player').href = location.origin + '/';\n  let count = 0, busy = false;\n  async function check() {\n    if (busy || document.hidden) return;\n    busy = true;\n    const abort = new AbortController(), timer = setTimeout(() => abort.abort(), 4000);\n    try {\n      const response = await fetch('/probe.json', {cache: 'no-store', signal: abort.signal});\n      if (!response.ok) throw Error('HTTP ' + response.status);\n      const s = await response.json();\n      $('status').textContent = `\u53cc\u5411 HTTP \u54cd\u5e94\u6b63\u5e38 \u00b7 ${++count} \u6b21`;\n      $('status').className = 'ok';\n      $('network').textContent = s.localReady ? '\u672c\u673a\u517c\u5bb9\u5730\u5740\u53ca\u672c\u5730\u8def\u7531\u5df2\u9a8c\u8bc1\u3002\u5f53\u524d\u6d4f\u89c8\u5668\u8bf7\u6c42\u5df2\u5230\u8fbe\u63a5\u6536 iPhone\u3002' : '\u666e\u901a\u5165\u53e3\u5df2\u8fde\u901a\uff1b\u517c\u5bb9\u5730\u5740\u72b6\u6001\uff1a' + s.phase;\n      $('details').textContent = [\n        '\u7248\u672c\uff1a' + s.version,\n        '\u6784\u5efa\uff1a' + (s.build || '\u672a\u77e5'),\n        '\u57df\u540d\uff1a' + s.domain,\n        'HTTPS\uff1a' + s.httpsStatus,\n        '\u5f53\u524d\u5165\u53e3\uff1a' + location.origin,\n        '\u63a5\u6536\u673a\u70ed\u70b9\uff1a' + (s.hotspotAddress || '\u672a\u68c0\u6d4b\u5230'),\n        '\u517c\u5bb9\u5730\u5740\uff1a' + s.compatibilityAddress,\n        '\u8fde\u63a5\u8fd4\u56de\u63a5\u53e3\uff1a' + (s.returnInterface || '\u672a\u786e\u8ba4'),\n        '\u70ed\u70b9\u56de\u7a0b\u68c0\u67e5\uff1a' + (s.returnRoutePending ? '\u540e\u53f0\u68c0\u67e5\u4e2d' : s.returnViaHotspot ? '\u901a\u8fc7' : '\u672a\u901a\u8fc7\u6216\u5f53\u524d\u4e3a\u672c\u673a\u6d4b\u8bd5'),\n        '\u8fde\u7eed\u5931\u8d25\uff1a' + (s.consecutiveFailures || 0) + '\uff1b\u81ea\u52a8\u91cd\u8bd5\u7b49\u5f85\uff1a' + Math.ceil((s.retryInMs || 0) / 1000) + ' \u79d2',\n        '\u540e\u53f0\u68c0\u67e5\u8017\u65f6\uff1a' + Math.round(s.routeCheckDurationMs || 0) + ' ms\uff1b\u7ed3\u679c\u5e74\u9f84\uff1a' + Math.round(s.routeCheckAgeMs ?? -1) + ' ms',\n        '\u672c\u8f6e HTTP \u63a2\u6d4b\u8bf7\u6c42\uff1a' + s.probeRequests,\n        '\u5730\u5740\u72b6\u6001\uff1a' + s.phase,\n        s.detail\n      ].join('\\n');\n      $('error').textContent = '';\n    } catch (error) {\n      $('status').className = '';\n      $('status').textContent = '\u9875\u9762\u66fe\u8fde\u901a\uff0c\u5f53\u524d\u54cd\u5e94\u4e2d\u65ad';\n      $('error').textContent = '\u8bf7\u68c0\u67e5\u63a5\u6536\u673a\u4e0a\u7684\u63a2\u6d4b\u5f00\u5173\u3001\u70ed\u70b9\u53ca Showcase \u524d\u53f0\u72b6\u6001\u3002' + error.message;\n    } finally { clearTimeout(timer); busy = false; }\n  }\n  check(); setInterval(check, 2000);\n  document.addEventListener('visibilitychange', () => { if (!document.hidden) check(); });\n})();\n";
static bool showcase_browser_asset(const char *path, const unsigned char **data, size_t *length, const char **mime) {
    if (!strcmp(path,"/")) { *data=(const unsigned char *)browser_index_html; *length=sizeof(browser_index_html)-1; *mime="text/html; charset=utf-8"; return true; }
    if (!strcmp(path,"/player.js")) { *data=(const unsigned char *)browser_player_js; *length=sizeof(browser_player_js)-1; *mime="application/javascript"; return true; }
    if (!strcmp(path,"/protocol.js")) { *data=(const unsigned char *)browser_protocol_js; *length=sizeof(browser_protocol_js)-1; *mime="application/javascript"; return true; }
    if (!strcmp(path,"/renderers.js")) { *data=(const unsigned char *)browser_renderers_js; *length=sizeof(browser_renderers_js)-1; *mime="application/javascript"; return true; }
    if (!strcmp(path,"/video-worker.js")) { *data=(const unsigned char *)browser_video-worker_js; *length=sizeof(browser_video-worker_js)-1; *mime="application/javascript"; return true; }
    if (!strcmp(path,"/probe")) { *data=(const unsigned char *)browser_probe_html; *length=sizeof(browser_probe_html)-1; *mime="text/html; charset=utf-8"; return true; }
    if (!strcmp(path,"/probe.js")) { *data=(const unsigned char *)browser_probe_js; *length=sizeof(browser_probe_js)-1; *mime="application/javascript"; return true; }
    return false;
}
